const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};
const header = (name) => headers[name.toLowerCase()] || headers[name] || '';
const timestamp = String(header('X-Aptohire-Timestamp'));
const supplied = String(header('X-Aptohire-Signature')).replace(/^sha256=/i, '').toLowerCase();
if (!/^\d{10}$/.test(timestamp) || Math.abs(Math.floor(Date.now()/1000)-Number(timestamp)) > 300) throw new Error('stale or invalid timestamp');
if (!body.run_id || !body.callback_url || !body.evidence || Object.keys(body).sort().join(',') !== 'callback_url,evidence,run_id') throw new Error('invalid job contract');
const callback = new URL(body.callback_url);
const callbackHost = callback.hostname.toLowerCase().replace(/\.$/, '');
const allowedCallbackHosts = String($env.N8N_CALLBACK_ALLOWED_HOSTS || '').split(',').map((host) => host.trim().toLowerCase().replace(/\.$/, '')).filter(Boolean);
if (callback.protocol !== 'https:' || callback.port && callback.port !== '443' || callback.pathname !== '/functions/v1/agent-callback' || callback.username || callback.password || callback.search || callback.hash ||
    !allowedCallbackHosts.includes(callbackHost) || !callbackHost.includes('.') || callbackHost.includes(':') || /^\d{1,3}(?:\.\d{1,3}){3}$/.test(callbackHost) ||
    callbackHost === 'localhost' || callbackHost.endsWith('.localhost') || callbackHost.endsWith('.local') || callbackHost.endsWith('.internal') || callbackHost.endsWith('.test') || callbackHost.endsWith('.invalid')) throw new Error('invalid callback URL');
const provider = new URL($env.N8N_LLM_CHAT_COMPLETIONS_URL);
const providerHost = provider.hostname.toLowerCase().replace(/\.$/, '');
const allowedProviderHosts = String($env.N8N_LLM_ALLOWED_HOSTS || '').split(',').map((host) => host.trim().toLowerCase().replace(/\.$/, '')).filter(Boolean);
if (provider.protocol !== 'https:' || provider.username || provider.password || provider.search || provider.hash ||
    (provider.port && provider.port !== '443') || !provider.pathname.endsWith('/chat/completions') ||
    !allowedProviderHosts.includes(providerHost) || !providerHost.includes('.') || providerHost.includes(':') || /^\d{1,3}(?:\.\d{1,3}){3}$/.test(providerHost) ||
    providerHost === 'localhost' || providerHost.endsWith('.localhost') || providerHost.endsWith('.local') ||
    providerHost.endsWith('.internal') || providerHost.endsWith('.test') || providerHost.endsWith('.invalid'))
  throw new Error('invalid provider endpoint configuration');
const raw = JSON.stringify(body);
const expected = crypto.createHmac('sha256', $env.N8N_WEBHOOK_SECRET).update(`${timestamp}.${raw}`).digest('hex');
const a = Buffer.from(expected, 'hex'); const b = Buffer.from(supplied, 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a,b)) throw new Error('invalid HMAC');
return [{json:{run_id:body.run_id,callback_url:body.callback_url,evidence:body.evidence}}];

const crypto = require('crypto');
const base = $('Verify HMAC and Contract').first().json;
const response = $input.first().json;
const content = response?.choices?.[0]?.message?.content;
if (typeof content !== 'string') throw new Error('model returned no JSON content');
let raw; try { raw = JSON.parse(content); } catch { throw new Error('model output is not JSON'); }
const keys = ['functionality','quality','ui_accessibility','testing','documentation','problem_solving','communication'];
if (raw.rubric_version !== 'web-frontend@1' || !Array.isArray(raw.criteria) || raw.criteria.length !== 7) throw new Error('model output failed audit schema precheck');
const allowedRefs = new Set((base.evidence.evidence || []).map((item) => item.ref).filter((ref) => typeof ref === 'string'));
const seen = new Set();
const criteria = raw.criteria.map((item) => { if (!keys.includes(item.key) || seen.has(item.key)) throw new Error('invalid or duplicate rubric key'); seen.add(item.key); const evidence = (Array.isArray(item.evidence) ? item.evidence : []).filter((citation) => allowedRefs.has(citation.evidence_ref)).slice(0,8).map((citation) => ({evidence_ref:citation.evidence_ref, ...(typeof citation.excerpt === 'string' ? {excerpt:citation.excerpt.slice(0,1200)} : {})})); return {key:item.key,score:Number(item.score),confidence:Number(item.confidence),rationale:String(item.rationale || '').slice(0,280),insufficient_evidence:Boolean(item.insufficient_evidence),evidence}; });
if (seen.size !== 7) throw new Error('incomplete rubric');
const output = {rubric_version:'web-frontend@1',prompt_version:'n8n-audit@1',overall_score:Number(raw.overall_score),confidence:Number(raw.confidence),summary:String(raw.summary || '').slice(0,600),criteria,transcript:Array.isArray(raw.transcript)?raw.transcript.slice(0,200).map((x)=>({'start_seconds':Number(x['start_seconds']),'text':String(x['text']||'').slice(0,1200)})):[],visual_observations:Array.isArray(raw.visual_observations)?raw.visual_observations.slice(0,30).map((x)=>String(x).slice(0,500)):[],next_steps:Array.isArray(raw.next_steps)?raw.next_steps.slice(0,3).map((x)=>String(x).slice(0,500)):[],prompt_injection_attempt:Boolean(raw.prompt_injection_attempt)};
const evidence_refs = [...allowedRefs].slice(0,500);
const callback_body = JSON.stringify({run_id:base.run_id,output,evidence_refs});
const timestamp = String(Math.floor(Date.now()/1000));
const signature = crypto.createHmac('sha256', $env.CALLBACK_SECRET).update(`${timestamp}.${callback_body}`).digest('hex');
return [{json:{callback_url:base.callback_url,callback_body,timestamp,signature}}];
